void dst_log_delete(void)
{
  dst_vars.log_done  = FALSE ;
  dst_vars.log_count = FALSE ;
  memset(&dst_vars.log[0] , NULL , sizeof(Dst_Log) * DST_LOG_SIZE) ;

  if(nvfs_delete(nvfs_dst_log) == NVFS_OK) ;
   {
     #if DBG_DST == 1  
       dst_dbg_print("\nDst Log Deleted" , NULL , NULL) ;
     #endif
   }
}
